"""docich#4632: bounded answers for held scripted-scene and yes/no screens.

g1190's chapter-1 fresh run held a readable concert yes/no (うむッ!/いかんッ!)
for 107 observations -- the choice labels read but the hand never did -- and
held the animated throne chant for 57 observations because an owner kept
answering [] while the frame digest flickered. The fixes under test:

(1) a readable prompt whose hand stays unreadable past YES_NO_UNREAD_BOUND is
    answered with the measured default anyway (accept stays on the upper row;
    a decline choice walks to the lower row once, then confirms);
(2) an unreadable scripted-scene frame an owner keeps held gets a bounded A
    once the unchanged frame is confirmed by the two-digest blink rule;
(3) a concert/event hold past SCENE_HOLD_FORCE_MAX forces a response; a
    pending guarded choice (trade/beauty) stays fail-closed and is never
    answered blindly.
"""
from docich.hanjuku_speedrun.hanjuku import orchestrator as O
from docich.hanjuku_speedrun.hanjuku.flows import prompts as P
from docich.hanjuku_speedrun.hanjuku.os_layer.font import TextLine
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen


def _line(y, x, word):
    return TextLine(y, tuple((x + 8 * i, ch) for i, ch in enumerate(word)))


def _prompt(text, hand=None):
    return Screen([], hand, text, kind='yes_no')


UNCLASSIFIED = 'たまごを つかいますか?\nうむッ!\nいかんッ!'
TRADE = 'しょうぐんどうしのトレードだ!\nうむッ!\nいかんッ!'


def test_a_readable_prompt_with_an_unreadable_hand_is_held_then_answered():
    """The Sugiyama concert invite case: labels read, the hand never does."""
    screen = _prompt(UNCLASSIFIED)
    mem = {}
    for _ in range(P.YES_NO_ACCEPT_SETTLE):
        assert P.yes_no_step(screen, mem) == []
    assert P.yes_no_step(screen, mem) == [P.pad('a')]
    rec = mem['_records'][-1]
    assert rec['decision'] == 'yes_no_forced_answer'
    assert rec['choice'] == 'うむッ!'
    assert rec['strategy_variant'] == 'unclassified_prompt'
    assert sum(1 for r in mem['_records'] if r['decision'] == 'situation_held') \
        == P.YES_NO_ACCEPT_SETTLE


def test_the_accept_settle_is_shorter_than_the_reviewed_decline_bound():
    """Reviewed choices keep the long bound: only the default accept hurries."""
    assert P.YES_NO_ACCEPT_SETTLE < P.YES_NO_UNREAD_BOUND
    decline = _prompt(TRADE)
    mem = {}
    for _ in range(P.YES_NO_UNREAD_BOUND):
        assert P.yes_no_step(decline, mem) == []
    assert P.yes_no_step(decline, mem) == [P.pad('down')]


def test_a_decline_choice_moves_to_the_lower_row_once_then_confirms():
    screen = _prompt(TRADE)
    mem = {}
    for _ in range(P.YES_NO_UNREAD_BOUND):
        assert P.yes_no_step(screen, mem) == []
    assert P.yes_no_step(screen, mem) == [P.pad('down')]
    assert mem['_records'][-1]['decision'] == 'yes_no_forced_move'
    assert mem['_records'][-1]['choice'] == 'いかんッ!'
    assert P.yes_no_step(screen, mem) == [P.pad('a')]
    rec = mem['_records'][-1]
    assert rec['decision'] == 'yes_no_forced_answer'
    assert rec['choice'] == 'いかんッ!'
    # The one down press already reached the decline row: no second move.
    assert P.yes_no_step(screen, mem) == [P.pad('a')]


def test_forced_presses_are_capped_per_prompt_episode():
    screen = _prompt(UNCLASSIFIED)
    mem = {}
    pressed = 0
    for _ in range(P.YES_NO_UNREAD_BOUND + P.YES_NO_FORCED_MAX + 5):
        if P.yes_no_step(screen, mem):
            pressed += 1
    assert pressed == P.YES_NO_FORCED_MAX
    assert P.yes_no_step(screen, mem) == []


def test_a_new_prompt_restarts_the_episode():
    mem = {}
    screen = _prompt(UNCLASSIFIED)
    for _ in range(P.YES_NO_ACCEPT_SETTLE + 1):
        P.yes_no_step(screen, mem)
    other = _prompt('べつの しつもん ですか?\nうむッ!\nいかんッ!')
    assert P.yes_no_step(other, mem) == []
    assert mem['yes_no_unread']['held'] == 1


def test_a_move_already_sent_marks_the_cursor_off_default():
    """A readable move toward the decline row counts as 'moved': if the hand
    then blinks out, the forced answer confirms without walking down again
    (a second down could wrap back to the accept row)."""
    screen = Screen([_line(167, 24, 'しょうぐんどうしのトレードだ!'),
                     _line(183, 184, 'うむッ!'), _line(199, 184, 'いかんッ!')],
                    (162, 177, 180, 190), TRADE, kind='yes_no')
    mem = {}
    assert P.yes_no_step(screen, mem) == [P.pad('down')]
    unreadable = _prompt(TRADE)
    for _ in range(P.YES_NO_UNREAD_BOUND):
        assert P.yes_no_step(unreadable, mem) == []
    assert P.yes_no_step(unreadable, mem) == [P.pad('a')]
    assert not any(r['decision'] == 'yes_no_forced_move' for r in mem['_records'])


def test_a_visible_hand_still_answers_without_touching_the_hold_state():
    screen = Screen([_line(167, 24, 'ごあいて ねがえぬか?'),
                     _line(183, 184, 'うむッ!'), _line(199, 184, 'いかんッ!')],
                    (162, 177, 180, 190), 'ごあいて ねがえぬか?\nうむッ!\nいかんッ!',
                    kind='yes_no')
    mem = {}
    assert P.yes_no_step(screen, mem) == [P.pad('a')]
    assert mem['_records'][-1]['strategy_variant'] == 'accept_duel'
    assert 'yes_no_unread' not in mem


