def _scene(kind='unknown', text=''):
    return Screen([], None, text, kind=kind)


def test_a_long_concert_hold_forces_an_answer():
    mem, screen = {}, _scene()
    for _ in range(O.SCENE_HOLD_FORCE_MAX - 1):
        assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                        guarded=False, blocked=False) is None
    assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                    guarded=False, blocked=False) == [O.pad('a')]
    rec = mem['_records'][-1]
    assert rec['decision'] == 'scene_hold_forced'
    assert rec['observed_metric']['sequence'] == 1


def test_the_monitor_survives_the_concert_event_phase_flicker():
    """The reported stall logged alternating concert/event on the same screen."""
    mem, screen = {}, _scene()
    for i in range(O.SCENE_HOLD_FORCE_MAX - 1):
        phase = 'concert' if i % 2 else 'event'
        assert O.scene_hold_forced_step(screen, mem, phase, 'unknown', [],
                                        guarded=False, blocked=False) is None
    assert O.scene_hold_forced_step(screen, mem, 'event', 'unknown', [],
                                    guarded=False, blocked=False) == [O.pad('a')]


def test_a_guarded_hold_is_never_forced():
    """A pending unconfirmed trade/beauty choice keeps its fail-closed
    contract: the monitor must never send a blind key to it."""
    mem, screen = {}, _scene()
    for _ in range(O.SCENE_HOLD_FORCE_MAX * 2):
        assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                        guarded=True, blocked=False) is None
    assert not any(r['decision'].startswith('scene_hold_forced')
                   for r in mem.get('_records', ()))


def test_an_interleaved_input_or_guard_pause_keeps_the_episode():
    """An observation that planned an input -- or sat under a guard -- keeps
    the episode and its count; it just does not grow the hold count."""
    mem, screen = {}, _scene()
    for _ in range(O.SCENE_HOLD_FORCE_MAX - 2):
        O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                 guarded=False, blocked=False)
    # One planned input and one guarded observation interleave.
    assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [O.pad('x')],
                                    guarded=False, blocked=False) is None
    assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                    guarded=True, blocked=False) is None
    # Two more held observations reach the bound and force the answer.
    assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                    guarded=False, blocked=False) is None
    assert O.scene_hold_forced_step(screen, mem, 'concert', 'unknown', [],
                                    guarded=False, blocked=False) == [O.pad('a')]


def test_forced_sequences_are_bounded_per_episode():
    mem, screen = {}, _scene()
    pressed = sum(bool(O.scene_hold_forced_step(screen, mem, 'event', 'unknown', [],
                                              guarded=False, blocked=False))
                  for _ in range(O.SCENE_HOLD_FORCE_MAX * 8))
    assert pressed == O.SCENE_HOLD_FORCE_SEQUENCES
    assert any(r['decision'] == 'scene_hold_forced_exhausted' for r in mem['_records'])


def test_owned_and_other_phase_screens_are_left_alone():
    for phase, kind, actions, blocked, watch in (
            ('concert', 'unknown', [], True, False),          # a bounded transaction owns it
            ('concert', 'unknown', [O.pad('a')], False, True),  # input already planned
            ('field', 'unknown', [], False, False),           # outside scripted phases
            ('concert', 'month_menu', [], False, False)):     # a menu kind owns itself
        mem = {}
        for _ in range(O.SCENE_HOLD_FORCE_MAX * 2):
            assert O.scene_hold_forced_step(_scene(kind), mem, phase, kind, actions,
                                          guarded=False, blocked=blocked) is None
        assert not any(r['decision'].startswith('scene_hold_forced')
                       for r in mem.get('_records', ()))
        # A planned-input observation keeps an empty watch; the others pop it.
        assert ('scene_hold_forced' in mem) is watch
        if watch:
            assert mem['scene_hold_forced']['n'] == 0


